SELECT
m.*
FROM
    sys_menu m
WHERE m.del_flag != #{pageDTO.delFlag}

    AND m.parent_id = #{pageDTO.parentId}


    AND m.id IN

        #{id}



    AND m.menu_type = #{pageDTO.menuType}


    AND (
        EXISTS (
        SELECT 1 FROM sys_role_menu_rel rmr
        JOIN sys_user_role_rel urr ON rmr.role_id = urr.role_id
        WHERE rmr.menu_id = m.id AND urr.user_id = #{pageDTO.userId}
        )
    )

WITH all_valid_menus AS ( SELECT DISTINCT m.id FROM sys_user_role_rel urr INNER JOIN sys_role_menu_rel rmr ON urr.role_id = rmr.role_id INNER JOIN sys_menu m ON rmr.menu_id = m.id WHERE m.del_flag != 2 AND urr.user_id = #{userId}
AND m.menu_type IN
#{menu}
AND m.menu_type NOT IN
#{menu}
) SELECT m.* FROM sys_menu m INNER JOIN all_valid_menus avm ON m.id = avm.id WHERE m.del_flag != 2

SELECT
m.*
FROM
sys_menu m
WHERE
m.del_flag != 2
AND m.module_id = #{moduleId}
AND m.menu_type = #{menuType}
AND m.mac = #{mac}

SELECT
    m.*
FROM
sys_menu m
WHERE
m.module_id = #{moduleId}
AND m.menu_type = #{menuType}
AND m.mac = #{mac}
ORDER BY m.create_time DESC
LIMIT 1
